from typing import Optional
class Node: pass
def find(index: dict[str, Node], key: str) -> Optional[Node]:
    return index.get(key, None)

class Graph:
    def __init__(self, nodes, edges):
        self.nodes = set(nodes)
        incoming = {}
        for source, target in edges:
            assert source in nodes and target in nodes
            incoming.setdefault(target, []).append(source)
        self._incoming = incoming
    def parents(self, target: str) -> list[str]:
        assert target in self.nodes
        return self._incoming.get(target, [])

